-- Aprovacao por empresa: company_members.status ganha 'pending' (aguardando aprovacao do admin da empresa)
-- e 'blocked' (bloqueado NA empresa). Login exige vinculo 'active' na empresa do endereco.
-- Rollback: voltar o ENUM para ('active','left','removed') (antes, converter pending/blocked) e recriar
-- view_user_manager a partir de 202610061724_replace_view.sql.
ALTER TABLE `company_members`
  MODIFY COLUMN `status` ENUM('pending','active','blocked','left','removed') NOT NULL DEFAULT 'active';

-- view_user_manager: um registro por usuario e empresa (vinculo pending/active/blocked), com company_id e cm_status.
CREATE OR REPLACE VIEW `view_user_manager` AS select `um`.`id` AS `id`,`cmx`.`company_id` AS `company_id`,`cmx`.`status` AS `cm_status`,`um`.`username` AS `um_username`,`um`.`status` AS `um_status`,`um`.`user_role_id` AS `um_user_role_id`,`um`.`last_login_at` AS `um_last_login_at`,`uc`.`id` AS `uc_id`,`uc`.`uuid` AS `uc_uuid`,`uc`.`name` AS `uc_name`,`uc`.`email` AS `uc_email`,`uc`.`phone` AS `uc_phone`,`uc`.`whatsapp` AS `uc_whatsapp`,`uc`.`cpf` AS `uc_cpf`,`uc`.`cep` AS `uc_cep`,`uc`.`address` AS `uc_address`,`ur`.`slug` AS `ur_role_slug`,`ur`.`name` AS `ur_role_name`,`ur`.`id` AS `ur_role_id`,`ur`.`description` AS `ur_role_description`,`uc`.`user_manager_id` AS `uc_user_manager_id`,`uc`.`created_at` AS `uc_created_at`,`uc`.`updated_at` AS `uc_updated_at`,`uc`.`deleted_at` AS `uc_deleted_at`,`ur`.`id` AS `ur_id`,`ur`.`name` AS `ur_name`,`ur`.`slug` AS `ur_slug`,`ur`.`description` AS `ur_description`,`ur`.`status` AS `ur_status`,`ur`.`created_at` AS `ur_created_at`,`ur`.`updated_at` AS `ur_updated_at`,`ur`.`deleted_at` AS `ur_deleted_at`,`um`.`created_at` AS `created_at`,`um`.`updated_at` AS `updated_at`,`um`.`deleted_at` AS `deleted_at` from (((`codeigniter54900_db`.`user_manager` `um` join `codeigniter54900_db`.`company_members` `cmx` on(((`cmx`.`user_manager_id` = `um`.`id`) and (`cmx`.`status` in ('pending','active','blocked')) and (`cmx`.`deleted_at` is null)))) left join `codeigniter54900_db`.`user_profiles` `uc` on(((`uc`.`user_manager_id` = `um`.`id`) and (`uc`.`deleted_at` is null)))) left join `codeigniter54900_db`.`user_roles` `ur` on(((`ur`.`id` = `um`.`user_role_id`) and (`ur`.`deleted_at` is null))));
